  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'IL MAKIAGE Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/il-makiage/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/il-makiage/', 'directory_listing', 'affiliate_program', 'LinkClicky''s IL MAKIAGE program page (fetched via search result; page last updated March 11, 2024) lists the affiliate platform as Impact and the commission as 5% per sale, described as ''what''s officially listed with their affiliate program''. However, Shopper.com lists the same program at 5-10% payout and LinkApprove lists up to 12% per sale on a 30-day cookie. Because the published figures conflict (5% vs 5-10% vs up to 12%), commission_rate is recorded as null rather than guessing. No earnings-cap statement or creator count is published, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
