  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'UASLIDER Affiliate Program', 'https://uaslider.com/pages/affiliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uaslider.com/pages/affiliate', 'brand_site', 'affiliate_program', 'UASLIDER''s own affiliate page (fetched in full) states: 15% commission on every order placed with a link or code; partners rise to 20% after at least 15 confirmed orders and at least 6 posts/reels in a 90-day period; 30-day cookie; monthly payouts via PayPal once the balance reaches $50; a personal 10% follower discount code; applications reviewed by hand, with 5,000+ Instagram followers (or comparable TikTok views) the usual bar for the paid tier. Under-5,000-follower applicants are offered a separate Creator track of free product plus a code instead of cash commission, so smaller creators should note the paid tier is not automatic. No earnings-cap statement appears, so commission_cap is unknown; no creator count is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 16, 9, 7, 3, '["15% base commission rising to 20%, with cookie and payout terms published on the brand''s own page", "Clear, detailed program terms including content and tagging rules", "Paid tier usually expects 5,000+ followers; smaller creators start on a free-product Creator track", "Small niche brand (nail decals), so reach and sales volume are unproven"]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Elyel Beauty', 'https://af.uppromote.com/elyel-beauty/register', 'Small independent skincare brand running its own affiliate program on UpPromote: a standard 15% commission on referral sales, with brand ambassadors receiving 20% and possible lifetime commission at the brand''s discretion. NOTE: the website recorded here is the brand''s program registration page; the brand''s standalone storefront URL and country were not published on the program page and could not be confirmed.', null, 'published') returning id into bid;
