  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Elyel Beauty Affiliate Program', 'https://af.uppromote.com/elyel-beauty/register', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://af.uppromote.com/elyel-beauty/register', 'brand_site', 'affiliate_program', 'Elyel Beauty''s own UpPromote registration page (fetched in full) states: ''All affiliates will be paid based on commission which is 15%''; ambassadors receive 20% commission and ''may be offered lifetime commission under our sole discretion''; contact email info.elyel@gmail.com; Instagram @elyel_radiant_skin. Applications can be approved or rejected at the brand''s discretion. Transparency note: the page''s terms are the platform''s standard template and include a conditional clause (section 5) under which, IF a ''Network'' tab is activated, affiliates could earn commission on downline affiliates'' orders; the base program itself pays 15% on the affiliate''s own referral sales. No earnings-cap statement appears, so commission_cap is unknown; no creator count is published, so creator_saturation is unknown. The page does not state the brand''s country or a standalone storefront URL.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 11, 15, 14, 8, 2, '["15% standard commission (20% for ambassadors) published on the program''s own registration page", "Published contact email info.elyel@gmail.com", "Very small, little-known brand; storefront and country not confirmed from the program page", "Terms are a platform template, including a conditional downline clause, which tempers credibility"]'::jsonb);
