  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bravodm.com/brands/tubbytodd', 'directory_listing', 'affiliate_program', 'BravoDM''s Tubby Todd creator-program page (facts checked October 2026) states the program targets parenting and baby-care creators promoting bath and skincare products for babies and kids, runs through an affiliate network, and is listed at tubbytodd.aspireiq.com/join/tubby-todd-bath-co-partnerships, linked from tubbytodd.com''s homepage. Published commission figures conflict: a bath-and-body program roundup lists 10% with a 30-day cookie, Lasso lists up to 11.25% with a 14-day cookie, and Shopper.com lists up to 1.2%. Because the figures conflict, commission_rate is recorded as null. A creator''s post of a brand DM indicates the program looks for creators with 1,000+ followers posting at least weekly. No earnings-cap statement or creator count is published, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
