  insert into public.brands (name, website, description, country, status) values ('OUAI', 'https://theouai.com', 'US prestige haircare and body brand (pronounced ''way'') founded by a celebrity hairstylist, sold DTC and at major beauty retailers. An affiliate program is listed through Sovrn Commerce and other directories, but published rate figures conflict and the Sovrn listing itself is unverified, so no rate is recorded.', 'United States', 'published') returning id into bid;
