  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/186000/ouai-affiliate-program', 'network_listing', 'affiliate_program', 'Sovrn Commerce''s OUAI merchant page (fetched via search result) explicitly states that OUAI''s current commission rates through Sovrn ''could not be independently verified'' and that a current OUAI partnership with Sovrn ''could not be independently confirmed''. Shopper.com lists the OUAI affiliate program at up to 5.99% payout per sale, while a hair-program roundup claims typically 10-15%. Because the sources conflict and the network listing is unverified, commission_rate is recorded as null and this entry is flagged needs_review. No earnings-cap statement or creator count is published, so commission_cap and creator_saturation are unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 7, 7, 8, 5, '["Prestige haircare brand with strong social visibility and creator content", "Affiliate access is listed through Sovrn Commerce and Shopper.com", "Rate sources conflict and the Sovrn listing is explicitly unverified, so the rate is left null and flagged for review", "No cap or creator-count information is published"]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Olive & June', 'https://oliveandjune.com', 'US at-home nail care brand selling manicure systems, polishes, treatments and press-ons. A program roundup lists an Olive & June affiliate program at up to 12% with a 30-day cookie, and the brand also runs ambassador routes (including a campus ambassador application); the rate is not published on the brand''s own pages, so it is recorded as null.', 'United States', 'published') returning id into bid;
