  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Olive & June Affiliate / Ambassador Program', 'https://oliveandjune.com/campus-ambassador-application', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://umatechnology.org/12-best-nail-affiliate-programs-in-2025-top-offers-2/', 'directory_listing', 'affiliate_program', 'A nail affiliate-program roundup (fetched via search result) lists an ''Olive & June Affiliate Program'' with commission ''up to 12%'' and a 30-day cookie, covering nail kits, polishes, tools and accessories. A single ''up to'' figure from a roundup is not a published rate, so commission_rate is recorded as null. Separately, coverage of the brand''s ambassador program (Lemon8) references an application at oliveandjune.com/campus-ambassador-application and describes ambassador perks centered on product and early access rather than a published commission. No earnings-cap statement or creator count is published, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
