  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/illamasqua-us/', 'directory_listing', 'affiliate_program', 'Lasso''s Illamasqua US program page (fetched in full) lists commission as ''1.6% and 8% Per Sale'' with a 30-day cookie, and its join link routes to ui.awin.com, identifying Awin as the network. The two-figure rate is not explained on the page, and Shopper.com separately lists the Illamasqua program at up to 5-10% payout. Because the published figures are ambiguous and conflicting, commission_rate is recorded as null rather than picking one. No earnings-cap statement or creator count is published, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
