  insert into public.brands (name, website, description, country, status) values ('Piping Rock', 'https://www.pipingrock.com', 'Large direct-to-consumer vitamins, supplements, essential oils and wellness retailer (2,000+ products) founded in 2011. Its affiliate program is powered by Impact: affiliates earn a 20% base commission with a 30-day cookie, paid monthly (processed about 45 days after month end). The brand also sells through TikTok Shop at distinct rates. Its affiliate page headline says ''Unlimited income possibilities,'' which is marketing language rather than an explicit no-cap statement in program terms, so the earnings cap is recorded as unknown.', 'United States', 'published') returning id into bid;
