  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.pipingrock.com/pages/affiliate-program', 'official_site', 'affiliate', 'Piping Rock''s own affiliate program page, fetched in full: the program is powered by Impact (the Apply Now button routes to app.impact.com), pays a 20% base commission with a 30-day cookie, and pays monthly with payments processed about 45 days after month end, across 2,000+ products; the page also notes the brand sells via TikTok Shops at distinct rates and publishes the contact customercare@pipingrock.com and phone 1-800-544-1925. The headline ''Unlimited income possibilities'' is not an explicit statement in the program terms that earnings are uncapped, so under the strict filter the cap stays unknown. No creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 16, 10, 8, 4, '{"compensation": "20% base commission is strong for the wellness category, with a 30-day cookie and monthly payouts; no cap statement is published.", "contact_access": "A published customer-care email and phone on the program page, but no dedicated partnerships or creator contact is published.", "credibility": "Large, long-running US wellness retailer with the full program terms published on its own domain.", "niche_fit": "Vitamins, supplements and essential oils are core wellness-creator content with a very broad 2,000+ product catalog to build videos around.", "opportunity_availability": "Open application through Impact from the brand''s own affiliate page.", "ugc_evidence": "A standard network affiliate program; no structured creator/ambassador content program is published, so UGC evidence is moderate."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Proper Good', 'https://eatpropergood.com', 'Shelf-stable ready-to-eat meals brand (soups, chilis, oatmeals, pastas and broths) with plant-based, keto and gluten-free lines, sold direct and at Target, Walmart and Hy-Vee; featured on Shark Tank (Season 13). Its affiliate program runs on ShareASale and pays 20% per sale with a long 90-day cookie. No earnings-cap statement and no creator count are published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
