  insert into public.brands (name, website, description, country, status) values ('Jot', 'https://jot.co', 'Maker of Ultra Coffee, a 20x concentrated liquid coffee sold by subscription direct to consumers. Its official Awin merchant profile advertises ''up to $25 commission on each subscription'' — a flat bounty ceiling. Third-party directories report conflicting percentage rates (15% per sale, up to 30%, 10%) that the network listing does not corroborate, so commission_rate is null with the conflict documented. No earnings-cap statement and no creator count are published.', 'United States', 'published') returning id into bid;
