  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Jot Affiliate Program on Awin — up to $25 commission per new subscription (flat bounty per the official network profile)', 'https://ui.awin.com/merchant-profile/73267', 'https://ui.awin.com/merchant-profile/73267', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/73267', 'affiliate_network', 'affiliate', 'Jot''s official Awin merchant profile, fetched directly: it describes Ultra Coffee (20x concentrated coffee) sold via jot.co and states ''Earn up to $25 commission on each subscription!'' — a flat per-subscription bounty of up to $25. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/jot/', 'third_party', 'affiliate', 'Rate conflict: Lasso reports 15% per sale for Jot, theaffiliatemonkey reports up to 30% (via CJ), and other directories report 10% via ShareASale — none of these percentage figures is corroborated by the official Awin listing, which publishes only the up-to-$25 per-subscription bounty. Because the published rates conflict, commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 11, 6, 8, 4, '{"compensation": "The official Awin profile publishes a flat bounty of up to $25 per subscription, but third-party percentage reports conflict, so the rate is unresolved and scored conservatively.", "contact_access": "No published partnerships or creator contact found; application is through the network only.", "credibility": "Well-known DTC coffee brand; the program is confirmed on the network''s own merchant profile.", "niche_fit": "A distinctive concentrated-coffee product with a strong demo angle (one tablespoon per drink) for coffee and morning-routine creators.", "opportunity_availability": "Open application through Awin.", "ugc_evidence": "A standard network affiliate listing; no structured creator content program is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Copper Cow Coffee', 'https://coppercowcoffee.com', 'Vietnamese pour-over coffee brand selling single-serve pour-over sets, ground coffee, teas and natural creamers, founded in Los Angeles. Its affiliate program runs on ShareASale and pays 8% per sale with a 30-day cookie; multiple directories agree on the 8% figure, and reported average order value is about $50. No earnings-cap statement and no creator count are published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
