  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/copper-cow-coffee/', 'third_party', 'affiliate', 'Lasso''s Copper Cow Coffee page independently reports the same terms — 8% per sale, 30-day cookie, ShareASale — and buildapreneur''s coffee program roundup also reports 8% with a 30-day cookie, an average order value of $50.30 and an average commission of $4.14, so the 8% rate is consistent across sources.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 10, 6, 8, 4, '{"compensation": "8% per sale is below the food-category mid-band, partly offset by a reported ~$50 average order value; no cap statement is published.", "contact_access": "No published partnerships or creator contact found; application is through the network only.", "credibility": "Established DTC coffee brand; program terms are consistent across three independent directories.", "niche_fit": "Single-serve Vietnamese pour-over coffee is a visual, demo-friendly product for coffee creators.", "opportunity_availability": "Open application through ShareASale.", "ugc_evidence": "A standard network affiliate program; no structured creator content program is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Earthing', 'https://www.earthing.com', 'Grounding (earthing) products brand — grounding sheets, mats, patches and footwear — run by Earth FX, Inc. / Barefoot Sales Corp. Its affiliate program runs on Refersion under published terms: affiliates earn a one-time payment of between 10% and 20% of total order value (excluding shipping and taxes) per eligible referral, with a 180-day cookie and payouts via PayPal on the last calendar day of the month for sales from two months prior. Because the published rate is a range rather than a single figure, commission_rate is null with the range documented. The terms include a minimum-sales clause (at least $1,000 in affiliate sales in one of the previous six months) and forfeiture of unpaid commissions after six consecutive inactive months. No earnings-cap statement and no creator count are published.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://earthing.refersion.com/?oid=78650', 'https://earthing.refersion.com/?oid=78650', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Refersion', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://earthing.refersion.com/?oid=78650.', 'https://earthing.refersion.com/?oid=78650', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Earthing Affiliate Program — 10–20% of order value per eligible referral via Refersion, 180-day cookie, monthly PayPal payouts', 'https://earthing.refersion.com/?oid=78650', 'https://earthing.refersion.com/?oid=78650', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://earthing.refersion.com/?oid=78650', 'official_site', 'affiliate', 'Earthing.com''s official affiliate program terms on its Refersion portal, fetched in full: commission is ''a one-time payment calculated within a range between ten percent (10%) and twenty percent (20%) of the total order value,'' excluding shipping, handling and taxes; Refersion tracking cookies last 180 days; payouts are made via PayPal on the last calendar day of each month for sales recorded two calendar months earlier; unpaid commissions are forfeited after six consecutive inactive months, and Earthing may terminate affiliates who have not generated at least $1,000 in affiliate sales in at least one of the previous six months. Paid advertising and coupon/deal sites are prohibited. No statement that earnings are uncapped and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 12, 6, 8, 4, '{"compensation": "A 10\u201320% range with a long 180-day cookie is solid, but the exact rate an affiliate receives is not fixed in the published terms, and a $1,000-in-six-months minimum-sales clause applies.", "contact_access": "No published partnerships or creator contact found; application is through the Refersion portal only.", "credibility": "The original grounding-products brand with complete program terms published on its own program portal.", "niche_fit": "Grounding sheets and mats sit in the sleep/recovery wellness niche \u2014 a narrower but active creator category.", "opportunity_availability": "Open application through the brand''s Refersion portal.", "ugc_evidence": "A standard affiliate program with published terms; no structured creator content program is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bean Box', 'https://beanbox.com', 'Seattle-based coffee subscription service curating beans from local roasters, plus coffee gifts. Its affiliate program runs on ShareASale with a 30-day cookie. Published rates conflict across directories — LinkClicky reports 12% per sale as the ShareASale listing, one roundup reports 10% on the public affiliate page, and another reports a 5–10% sliding scale — so commission_rate is null with the conflict documented. No earnings-cap statement and no creator count are published.', 'United States', 'published') returning id into bid;
