  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bean Box Affiliate Program — ShareASale coffee subscription program, 30-day cookie (published rates conflict: 5–12%)', 'https://linkclicky.com/affiliate-program/bean-box/', 'https://linkclicky.com/affiliate-program/bean-box/', 'unverified', 'ugc');
