  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliatehelpcenter.com/coffee-affiliate-programs/', 'third_party', 'affiliate', 'Rate conflict: Affiliate Help Center reports Bean Box at 5–10% on a sliding scale based on monthly referrals, and outandbeyond''s coffee roundup reports 10% on the public-facing affiliate page versus 12% inside ShareASale. Because the published figures conflict, commission_rate is recorded as null.', 'needs_review', now());
