  insert into public.brands (name, website, description, country, status) values ('The Good Bean', 'https://thegoodbean.com', 'Plant-based snack brand making crunchy roasted chickpea snacks, fava bean protein crisps and chocolate-covered chickpeas — gluten-free, nut-free, non-GMO, kosher and vegan. Its affiliate program runs on ShareASale and pays 10% per sale with a long 90-day cookie. No earnings-cap statement and no creator count are published, so cap and saturation are unknown.', 'United States', 'published') returning id into bid;
