  insert into public.brands (name, website, description, country, status) values ('Wandering Bear Coffee', 'https://wanderingbearcoffee.com', 'Organic cold brew coffee brand selling bottled and boxed cold brew, cold brew on tap for offices, and canned cold brew lattes, direct to consumers and in retail (Whole Foods, Target, Costco). Its affiliate program runs on ShareASale with a 90-day cookie. Published rates conflict — LinkClicky reports 10% per sale, while another program analysis reports the structure varies by network, from 1% for returning customers to a $2 flat payment for new customers — so commission_rate is null with the conflict documented. No earnings-cap statement and no creator count are published.', 'United States', 'published') returning id into bid;
