  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/wandering-bear-coffee/', 'third_party', 'affiliate', 'LinkClicky''s Wandering Bear Coffee program listing (updated March 11, 2024): ShareASale platform, 10% commission per sale, 90-day cookie, website wanderingbearcoffee.com. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://craigcampbellseo.com/coffee-affiliate-programs', 'third_party', 'affiliate', 'Rate conflict: this coffee program analysis reports Wandering Bear is managed through several networks (Sovrn, Skimlinks, CJ Affiliate) with different commissions and cookie durations — typically a 30-day cookie, with rates varying from 1% for returning customers to $2 flat for new customers — which conflicts with LinkClicky''s flat 10% / 90-day ShareASale figures. Because the published rates conflict, commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 8, 6, 8, 4, '{"compensation": "Published rates conflict sharply (10% flat vs 1% returning / $2 flat new), so compensation is scored low until the live network terms are confirmed.", "contact_access": "No published partnerships or creator contact found; application is through the network only.", "credibility": "Established cold brew brand with national retail distribution; program existence is consistent across sources.", "niche_fit": "Organic cold brew in bottles, boxes and cans is easy to demo and fits coffee and office-routine content.", "opportunity_availability": "Open application through ShareASale.", "ugc_evidence": "A standard network affiliate program; sponsored creator posts exist in the wild, but no structured creator program is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vahdam Teas', 'https://www.vahdam.com', 'Direct-from-source Indian tea brand (VAHDAM) shipping loose-leaf teas, chai and wellness blends from Indian gardens to 100+ countries. Its affiliate program runs on ShareASale (managed by Gen3 Marketing, also listed on FlexOffers). Published rates conflict widely — LinkClicky lists a 4% base rate with a 30-day cookie, thrivershub reports 4–20% with a 4% default and double commission in the first month, and brandid.app reports 12–18% with a 60-day cookie — so commission_rate is null with the conflict documented. No earnings-cap statement and no creator count are published.', 'India', 'published') returning id into bid;
