  insert into public.brands (name, website, description, country, status) values ('Cultures for Health', 'https://www.culturesforhealth.com', 'Fermented-foods retailer selling starter cultures and kits for yogurt, kefir, sourdough, kombucha, cheese and fermented vegetables. It runs its own affiliate program (sign-up on its own website, tracked with affiliate software). Published rates conflict across directories — Post Affiliate Pro''s directory lists 5% with monthly PayPal payouts and a $100 minimum payout, Lasso reports up to 7.5%, and Shopper reports 5–10% — so commission_rate is null with the conflict documented. No earnings-cap statement and no creator count are published.', 'United States', 'published') returning id into bid;
