  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 13, 7, 8, 4, '{"compensation": "Published 10% per sale is a solid mid-range kitchenware rate; the 15-day cookie is on the shorter side.", "contact_access": "Join route is documented through program listings; no public creator contact email was found on a fetched page.", "credibility": "Well-reviewed DTC brand sold through its own site and retailers such as West Elm and Nordstrom.", "niche_fit": "Beautiful, minimal kitchen tools are natural cooking and kitchen-reset content; the small curated range films well.", "opportunity_availability": "Program is live and joinable now through the network listing.", "ugc_evidence": "The program is listed for bloggers and creators on Lasso and food-blogger program roundups, though the brand publishes no dedicated creator page."}'::jsonb);
