  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 6, 7, 8, 5, '{"compensation": "No rate can be honestly recorded: directories conflict at 4%, 8% and 10%, and the agreed 1-day cookie is the shortest in this batch.", "contact_access": "Application runs through CJ sign-up as documented by the program reviews; no public partnerships email was found on a fetched page.", "credibility": "Category-defining public audio brand with a long-standing network program.", "niche_fit": "Premium speakers and soundbars are core tech-review and smart-home content, with a reported ~$390 average order in network promotions.", "opportunity_availability": "Program is live and joinable now through CJ.", "ugc_evidence": "The CJ program is documented across multiple affiliate directories aimed at reviewers and publishers, though Sonos publishes no creator page of its own."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rolli Shades', 'https://www.rollishades.com', 'Custom motorized window shades (roller, cellular, roman and no-drill) controlled by remote, app and voice assistants, sold direct with design consultations. Its Awin merchant profile publishes 7–10% commission, a 60-day attribution window and average order values above $1,000.', 'United States', 'published') returning id into bid;
