  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 15, 7, 8, 4, '{"compensation": "7\u201310% on average orders above $1,000 with a 60-day window is the strongest per-sale economics in this batch.", "contact_access": "Application route is the Awin merchant profile; no public creator contact email was found on a fetched page.", "credibility": "Operating DTC shades brand with published network terms and a consultation-led sales model.", "niche_fit": "Smart shades are strong smart-home and room-makeover content, though the considered, high-ticket purchase narrows the audience.", "opportunity_availability": "Program is live and joinable now through Awin.", "ugc_evidence": "The Awin program is open to publishers; no creator-specific recruitment was found on a fetched page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('V TOWER', 'https://vtower.shop', 'Kitchen gadget brand selling through Amazon (palm peelers, cheese tools, prep gadgets). It runs its own creator-first affiliate program paying 10% of the sales Amazon counts for a creator''s link, plus Amazon Creator Connections campaign bonuses of 10–30%, $0.01 product samples for filming, and a paid-UGC partnership route.', 'United States', 'published') returning id into bid;
