  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://vtower.shop/blogs/news/kitchen-gadgets-affiliate-program-v-tower.', 'https://vtower.shop/blogs/news/how-to-join-the-v-tower-partner-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'V TOWER Affiliate Program (own program) — 10% of Amazon-counted sales, 14-day window, plus Creator Connections campaigns at 10–30%', 'https://vtower.shop/blogs/news/how-to-join-the-v-tower-partner-program', 'https://vtower.shop/blogs/news/kitchen-gadgets-affiliate-program-v-tower', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://vtower.shop/blogs/news/kitchen-gadgets-affiliate-program-v-tower', 'official_site', 'affiliate', 'V TOWER''s own program guide (brand''s site, figures dated November 13–18, 2026; fetched for this batch): join the affiliate program on vtower.shop for your own Amazon link and 10% of the sales Amazon counts for it, paid by V TOWER via PayPal about 4 weeks after each 14-day period ends, $25 minimum payout; or accept an Amazon Creator Connections campaign for a 10–30% bonus. The guide reports 617 creators have earned through its campaigns — a few-hundred-plus scale, which under the strict rule is not low, so saturation stays unknown. No earnings-cap statement is published, so cap stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://vtower.shop/blogs/news/how-to-join-the-v-tower-partner-program', 'official_site', 'affiliate', 'V TOWER''s own join guide (brand''s site, updated from the program page as it read November 18, 2026; fetched for this batch): sign-up needs only an email, a main channel link (the form''s example is a TikTok link) and a PayPal email — no Amazon Associates account and no minimum follower count; the creator''s Amazon link is ready in about 30 minutes, and sales count within 14 days of a click.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 17, 13, 9, 9, 3, '{"compensation": "10% of counted Amazon sales paid by the brand itself, with 10\u201330% Creator Connections bonuses on top; the 14-day window and $25 minimum are mid-pack.", "contact_access": "Open self-serve application on the brand''s own site with the full join process documented step by step.", "credibility": "Small, young Amazon-native brand; terms are unusually transparent but the track record is short.", "niche_fit": "Cheap, demonstrable kitchen gadgets are built for short-form demo videos and Amazon roundups.", "opportunity_availability": "Program is live now, connects instantly, and campaigns were open as of the brand''s November 2026 figures.", "ugc_evidence": "The brand''s own pages are written for creators: TikTok-first sign-up form, $0.01 filming samples, a paid-UGC route and published campaign earnings."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Field Company', 'https://fieldcompany.com', 'Cast iron cookware brand making smooth-polished skillets in the USA. Its own site runs a combined Creator & Affiliate Program page (powered by Dovetale) inviting creators and affiliates to apply; the commission rate is not published, so no rate is recorded.', 'United States', 'published') returning id into bid;
