  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fieldcompany.com/pages/collab', 'official_site', 'affiliate', 'Field Company''s own Creator & Affiliate Program page (fetched in full for this batch; the application runs via Dovetale, per the page''s uploads.dovetale.com assets): the brand invites creators and affiliates to apply through the page. No commission rate, earnings-cap statement or creator count is published anywhere on the page, so the rate is recorded as null and cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 5, 9, 8, 4, '{"compensation": "No commission rate is published anywhere fetched, so compensation cannot be graded above the floor.", "contact_access": "Direct application page on the brand''s own domain \u2014 the clearest contact route in this batch alongside V TOWER.", "credibility": "Established US-made cookware brand with national retail and press presence.", "niche_fit": "Cast iron cooking, seasoning and restoration content has a loyal creator niche, and the skillets are highly demonstrable.", "opportunity_availability": "The application page is live and accepting creators now.", "ugc_evidence": "The brand''s own page is explicitly a Creator & Affiliate Program, not a generic contact form."}'::jsonb);
