  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.earthrated.com/blogs/blog/earth-rated-is-officially-a-certified-b-corp', 'official_site', 'brand', 'Earth Rated''s own blog (fetched for this batch) confirms the brand is a certified B Corporation; company releases state it was founded in 2009 in Montreal, its bags are used by over 4.5 million people daily and sold in over 20,000 stores across 40+ countries.', 'verified', now());
