  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 9, 10, 7, 8, 4, '{"compensation": "Published 5% per sale on high-ticket purifiers (machines run several hundred dollars) can pay well per conversion despite the modest percentage.", "contact_access": "Application route is documented through the CJ listing; no public creator contact email was found on a fetched page.", "credibility": "Long-established US manufacturer whose purifiers are used in schools and medical settings.", "niche_fit": "Air quality, allergies and nursery/classroom clean-air content is a real home-health niche, though purifiers are a considered, infrequent purchase.", "opportunity_availability": "Program is live and joinable now through CJ.", "ugc_evidence": "The CJ listing is aimed at publishers and influencers generally; no creator-specific recruitment was found on a fetched page."}'::jsonb);
